-- --------------------------------------------------------------------------
-- Derived reads - MUST mirror the views in m001_initial.ts
-- --------------------------------------------------------------------------

-- Excludes reversals AND the originals they reversed. Use for ACTIVITY
-- counts ("doses given today"). Do NOT use for balances.
-- security_invoker is NOT optional. A Postgres view runs with its OWNER's
-- rights by default and therefore IGNORES row-level security, which would
-- expose every clinic to every signed-in user. This makes the view run as
-- the caller, so the policies on the underlying tables still apply.
-- DROP before CREATE, not CREATE OR REPLACE.
--
-- CREATE OR REPLACE VIEW refuses a changed column list, and the Supabase
-- SQL Editor runs this file as one transaction - so one refusal rolls back
-- everything and the view silently stays on its old definition. That is
-- exactly what happened when `level` was added. Nothing depends on these
-- views, so dropping them first is free and always works.
DROP VIEW IF EXISTS public.v_movement_effective;
CREATE VIEW public.v_movement_effective
  WITH (security_invoker = true) AS
SELECT m.* FROM public.stock_movements m
WHERE m.movement_type <> 'REVERSAL'
  AND NOT EXISTS (
    SELECT 1 FROM public.stock_movements r WHERE r.reverses_id = m.id
  );

-- Balances sum the RAW table on purpose: reversals cancel arithmetically,
-- which is the whole reason reversing entries are the right design.
DROP VIEW IF EXISTS public.v_stock_on_hand;
CREATE VIEW public.v_stock_on_hand
  WITH (security_invoker = true) AS
SELECT
  v.owner                          AS owner,
  v.id                             AS vaccine_id,
  v.name                           AS name,
  v.generic_name                   AS generic_name,
  v.unit_mode                      AS unit_mode,
  v.doses_per_vial                 AS doses_per_vial,
  v.min_balance_doses              AS min_balance_doses,
  v.is_active                      AS is_active,
  COALESCE(SUM(m.delta_doses), 0)  AS on_hand_doses,
  -- Mirrors stockLevel() in src/domain/stock.ts. Kept here rather than in
  -- the dashboard so there is ONE definition of "low": the web page must
  -- not re-derive it and quietly disagree with the phone.
  --
  -- The <= is deliberate and load-bearing. Firing at < instead means the
  -- warning never appears at exactly the safety limit, which is a silent
  -- stock-out (CLAUDE.md section 11, test 5).
  CASE
    WHEN COALESCE(SUM(m.delta_doses), 0) < 0 THEN 'NEGATIVE'
    WHEN COALESCE(SUM(m.delta_doses), 0) = 0 THEN 'OUT'
    WHEN v.min_balance_doses > 0
     AND COALESCE(SUM(m.delta_doses), 0) <= v.min_balance_doses THEN 'LOW'
    ELSE 'OK'
  END                              AS level
FROM public.vaccines v
LEFT JOIN public.stock_movements m
       ON m.vaccine_id = v.id
      AND m.owner = v.owner
      AND m.stock_source = 'CLINIC_STOCK'
WHERE v.deleted_at IS NULL
GROUP BY v.owner, v.id;

-- Per-device freshness. The dashboard leads with THIS, before any stock
-- number: a count read at home while a device has not synced for three
-- hours is wrong and looks authoritative.
DROP VIEW IF EXISTS public.v_device_activity;
CREATE VIEW public.v_device_activity
  WITH (security_invoker = true) AS
SELECT
  owner                    AS owner,
  device_id                AS device_id,
  COUNT(*)                 AS entries,
  MAX(recorded_at)         AS last_entry_at,
  MAX(synced_at)           AS last_synced_at
FROM public.stock_movements
GROUP BY owner, device_id;

GRANT SELECT ON public.v_movement_effective TO authenticated;
GRANT SELECT ON public.v_stock_on_hand      TO authenticated;
GRANT SELECT ON public.v_device_activity    TO authenticated;

-- --------------------------------------------------------------------------
-- Lock out the anonymous role entirely
-- --------------------------------------------------------------------------
-- Defence in depth, and it also makes this verifiable. Row-level security
-- already returns nothing to `anon` because every policy is TO authenticated,
-- but on an empty table "RLS is working" and "RLS is bypassed" look
-- identical from outside - both answer 200 with an empty list. Revoking the
-- grant makes `anon` answer 401 instead, so a single unauthenticated request
-- proves the clinic data is unreachable without a login.
--
-- Safe for the app: it sends the publishable key as `apikey` but also a user
-- JWT as `Authorization`, so it acts as `authenticated`, never as `anon`.
REVOKE ALL ON public.vaccines FROM anon;
REVOKE ALL ON public.patients FROM anon;
REVOKE ALL ON public.staff FROM anon;
REVOKE ALL ON public.lots FROM anon;
REVOKE ALL ON public.stock_movements FROM anon;
REVOKE ALL ON public.v_movement_effective FROM anon;
REVOKE ALL ON public.v_stock_on_hand      FROM anon;
REVOKE ALL ON public.v_device_activity    FROM anon;

